(ns clojure.core-meta)

;; Existing keys win: a var's own meta (a defn-attached :arglists) is
;; preserved; only the missing keys are filled from the oracle table.
(def ^:private fill (fn [m mm] (merge mm m)))

(when-let [v (resolve (quote clojure.core/*))] (alter-meta! v fill {:arglists (quote ([] [x] [x y] [x y & more])), :doc "Returns the product of nums. (*) returns 1. Does not auto-promote\n  longs, will throw on overflow. See also: *'"}))
(when-let [v (resolve (quote clojure.core/*'))] (alter-meta! v fill {:arglists (quote ([] [x] [x y] [x y & more])), :doc "Returns the product of nums. (*') returns 1. Supports arbitrary precision.\n  See also: *"}))
(when-let [v (resolve (quote clojure.core/*1))] (alter-meta! v fill {:doc "bound in a repl thread to the most recent value printed"}))
(when-let [v (resolve (quote clojure.core/*2))] (alter-meta! v fill {:doc "bound in a repl thread to the second most recent value printed"}))
(when-let [v (resolve (quote clojure.core/*3))] (alter-meta! v fill {:doc "bound in a repl thread to the third most recent value printed"}))
(when-let [v (resolve (quote clojure.core/*agent*))] (alter-meta! v fill {:doc "The agent currently running an action on this thread, else nil"}))
(when-let [v (resolve (quote clojure.core/*assert*))] (alter-meta! v fill {:doc "When set to logical false, 'assert' will omit assertion checks in\n  compiled code. Defaults to true."}))
(when-let [v (resolve (quote clojure.core/*clojure-version*))] (alter-meta! v fill {:doc "The version info for Clojure core, as a map containing :major :minor \n  :incremental and :qualifier keys. Feature releases may increment \n  :minor and/or :major, bugfix releases will increment :incremental. \n  Possible values of :qualifier include \"GA\", \"SNAPSHOT\", \"RC-x\" \"BETA-x\""}))
(when-let [v (resolve (quote clojure.core/*command-line-args*))] (alter-meta! v fill {:doc "A sequence of the supplied command line arguments, or nil if\n  none were supplied"}))
(when-let [v (resolve (quote clojure.core/*data-readers*))] (alter-meta! v fill {:doc "Map from reader tag symbols to data reader Vars.\n\n  When Clojure starts, it searches for files named 'data_readers.clj'\n  and 'data_readers.cljc' at the root of the classpath. Each such file\n  must contain a literal map of symbols, like this:\n\n      {foo/bar my.project.foo/bar\n       foo/baz my.project/baz}\n\n  The first symbol in each pair is a tag that will be recognized by\n  the Clojure reader. The second symbol in the pair is the\n  fully-qualified name of a Var which will be invoked by the reader to\n  parse the form following the tag. For example, given the\n  data_readers.clj file above, the Clojure reader would parse this\n  form:\n\n      #foo/bar [1 2 3]\n\n  by invoking the Var #'my.project.foo/bar on the vector [1 2 3]. The\n  data reader function is invoked on the form AFTER it has been read\n  as a normal Clojure data structure by the reader.\n\n  Reader tags without namespace qualifiers are reserved for\n  Clojure. Default reader tags are defined in\n  clojure.core/default-data-readers but may be overridden in\n  data_readers.clj, data_readers.cljc, or by rebinding this Var."}))
(when-let [v (resolve (quote clojure.core/*default-data-reader-fn*))] (alter-meta! v fill {:doc "When no data reader is found for a tag and *default-data-reader-fn*\n  is non-nil, it will be called with two arguments,\n  the tag and the value.  If *default-data-reader-fn* is nil (the\n  default), an exception will be thrown for the unknown tag."}))
(when-let [v (resolve (quote clojure.core/*e))] (alter-meta! v fill {:doc "bound in a repl thread to the most recent exception caught by the repl"}))
(when-let [v (resolve (quote clojure.core/*err*))] (alter-meta! v fill {:doc "A java.io.Writer object representing standard error for print operations.\n\n  Defaults to System/err, wrapped in a PrintWriter"}))
(when-let [v (resolve (quote clojure.core/*file*))] (alter-meta! v fill {:doc "The path of the file being evaluated, as a String.\n\n  When there is no file, e.g. in the REPL, the value is not defined."}))
(when-let [v (resolve (quote clojure.core/*flush-on-newline*))] (alter-meta! v fill {:doc "When set to true, output will be flushed whenever a newline is printed.\n\n  Defaults to true."}))
(when-let [v (resolve (quote clojure.core/*in*))] (alter-meta! v fill {:doc "A java.io.Reader object representing standard input for read operations.\n\n  Defaults to System/in, wrapped in a LineNumberingPushbackReader"}))
(when-let [v (resolve (quote clojure.core/*ns*))] (alter-meta! v fill {:doc "A clojure.lang.Namespace object representing the current namespace."}))
(when-let [v (resolve (quote clojure.core/*out*))] (alter-meta! v fill {:doc "A java.io.Writer object representing standard output for print operations.\n\n  Defaults to System/out, wrapped in an OutputStreamWriter"}))
(when-let [v (resolve (quote clojure.core/*print-dup*))] (alter-meta! v fill {:doc "When set to logical true, objects will be printed in a way that preserves\n  their type when read in later.\n\n  Defaults to false."}))
(when-let [v (resolve (quote clojure.core/*print-length*))] (alter-meta! v fill {:doc "*print-length* controls how many items of each collection the\n  printer will print. If it is bound to logical false, there is no\n  limit. Otherwise, it must be bound to an integer indicating the maximum\n  number of items of each collection to print. If a collection contains\n  more items, the printer will print items up to the limit followed by\n  '...' to represent the remaining items. The root binding is nil\n  indicating no limit."}))
(when-let [v (resolve (quote clojure.core/*print-level*))] (alter-meta! v fill {:doc "*print-level* controls how many levels deep the printer will\n  print nested objects. If it is bound to logical false, there is no\n  limit. Otherwise, it must be bound to an integer indicating the maximum\n  level to print. Each argument to print is at level 0; if an argument is a\n  collection, its items are at level 1; and so on. If an object is a\n  collection and is at a level greater than or equal to the value bound to\n  *print-level*, the printer prints '#' to represent it. The root binding\n  is nil indicating no limit."}))
(when-let [v (resolve (quote clojure.core/*print-meta*))] (alter-meta! v fill {:doc "If set to logical true, when printing an object, its metadata will also\n  be printed in a form that can be read back by the reader.\n\n  Defaults to false."}))
(when-let [v (resolve (quote clojure.core/*print-namespace-maps*))] (alter-meta! v fill {:doc "*print-namespace-maps* controls whether the printer will print\n  namespace map literal syntax. It defaults to false, but the REPL binds\n  to true."}))
(when-let [v (resolve (quote clojure.core/*print-readably*))] (alter-meta! v fill {:doc "When set to logical false, strings and characters will be printed with\n  non-alphanumeric characters converted to the appropriate escape sequences.\n\n  Defaults to true"}))
(when-let [v (resolve (quote clojure.core/*unchecked-math*))] (alter-meta! v fill {:doc "While bound to true, compilations of +, -, *, inc, dec and the\n  coercions will be done without overflow checks. While bound\n  to :warn-on-boxed, same behavior as true, and a warning is emitted\n  when compilation uses boxed math. Default: false."}))
(when-let [v (resolve (quote clojure.core/*warn-on-reflection*))] (alter-meta! v fill {:doc "When set to true, the compiler will emit warnings when reflection is\n  needed to resolve Java method calls or field accesses.\n\n  Defaults to false."}))
(when-let [v (resolve (quote clojure.core/+))] (alter-meta! v fill {:arglists (quote ([] [x] [x y] [x y & more])), :doc "Returns the sum of nums. (+) returns 0. Does not auto-promote\n  longs, will throw on overflow. See also: +'"}))
(when-let [v (resolve (quote clojure.core/+'))] (alter-meta! v fill {:arglists (quote ([] [x] [x y] [x y & more])), :doc "Returns the sum of nums. (+') returns 0. Supports arbitrary precision.\n  See also: +"}))
(when-let [v (resolve (quote clojure.core/-))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "If no ys are supplied, returns the negation of x, else subtracts\n  the ys from x and returns the result. Does not auto-promote\n  longs, will throw on overflow. See also: -'"}))
(when-let [v (resolve (quote clojure.core/-'))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "If no ys are supplied, returns the negation of x, else subtracts\n  the ys from x and returns the result. Supports arbitrary precision.\n  See also: -"}))
(when-let [v (resolve (quote clojure.core/->))] (alter-meta! v fill {:arglists (quote ([x & forms])), :doc "Threads the expr through the forms. Inserts x as the\n  second item in the first form, making a list of it if it is not a\n  list already. If there are more forms, inserts the first form as the\n  second item in second form, etc."}))
(when-let [v (resolve (quote clojure.core/->>))] (alter-meta! v fill {:arglists (quote ([x & forms])), :doc "Threads the expr through the forms. Inserts x as the\n  last item in the first form, making a list of it if it is not a\n  list already. If there are more forms, inserts the first form as the\n  last item in second form, etc."}))
(when-let [v (resolve (quote clojure.core/->Eduction))] (alter-meta! v fill {:arglists (quote ([xform coll])), :doc "Positional factory function for class clojure.core.Eduction."}))
(when-let [v (resolve (quote clojure.core/..))] (alter-meta! v fill {:arglists (quote ([x form] [x form & more])), :doc "form => fieldName-symbol or (instanceMethodName-symbol args*)\n\n  Expands into a member access (.) of the first member on the first\n  argument, followed by the next member on the result, etc. For\n  instance:\n\n  (.. System (getProperties) (get \"os.name\"))\n\n  expands to:\n\n  (. (. System (getProperties)) (get \"os.name\"))\n\n  but is easier to write, read, and understand."}))
(when-let [v (resolve (quote clojure.core//))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "If no denominators are supplied, returns 1/numerator,\n  else returns numerator divided by all of the denominators."}))
(when-let [v (resolve (quote clojure.core/<))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Returns non-nil if nums are in monotonically increasing order,\n  otherwise false."}))
(when-let [v (resolve (quote clojure.core/<=))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Returns non-nil if nums are in monotonically non-decreasing order,\n  otherwise false."}))
(when-let [v (resolve (quote clojure.core/=))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Equality. Returns true if x equals y, false if not. Same as\n  Java x.equals(y) except it also works for nil, and compares\n  numbers and collections in a type-independent manner.  Clojure's immutable data\n  structures define equals() (and thus =) as a value, not an identity,\n  comparison."}))
(when-let [v (resolve (quote clojure.core/==))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Returns non-nil if nums all have the equivalent\n  value (type-independent), otherwise false"}))
(when-let [v (resolve (quote clojure.core/>))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Returns non-nil if nums are in monotonically decreasing order,\n  otherwise false."}))
(when-let [v (resolve (quote clojure.core/>=))] (alter-meta! v fill {:arglists (quote ([x] [x y] [x y & more])), :doc "Returns non-nil if nums are in monotonically non-increasing order,\n  otherwise false."}))
(when-let [v (resolve (quote clojure.core/NaN?))] (alter-meta! v fill {:arglists (quote ([num])), :doc "Returns true if num is NaN, else false"}))
(when-let [v (resolve (quote clojure.core/Throwable->map))] (alter-meta! v fill {:arglists (quote ([o])), :doc "Constructs a data representation for a Throwable with keys:\n    :cause - root cause message\n    :phase - error phase\n    :via - cause chain, with cause keys:\n             :type - exception class symbol\n             :message - exception message\n             :data - ex-data\n             :at - top stack element\n    :trace - root cause stack elements"}))
(when-let [v (resolve (quote clojure.core/abs))] (alter-meta! v fill {:arglists (quote ([a])), :doc "Returns the absolute value of a.\n  If a is Long/MIN_VALUE => Long/MIN_VALUE\n  If a is a double and zero => +0.0\n  If a is a double and ##Inf or ##-Inf => ##Inf\n  If a is a double and ##NaN => ##NaN"}))
(when-let [v (resolve (quote clojure.core/aclone))] (alter-meta! v fill {:arglists (quote ([array])), :doc "Returns a clone of the Java array. Works on arrays of known\n  types."}))
(when-let [v (resolve (quote clojure.core/add-tap))] (alter-meta! v fill {:arglists (quote ([f])), :doc "adds f, a fn of one argument, to the tap set. This function will be called with anything sent via tap>.\n  This function may (briefly) block (e.g. for streams), and will never impede calls to tap>,\n  but blocking indefinitely may cause tap values to be dropped.\n  Remember f in order to remove-tap"}))
(when-let [v (resolve (quote clojure.core/add-watch))] (alter-meta! v fill {:arglists (quote ([reference key fn])), :doc "Adds a watch function to an agent/atom/var/ref reference. The watch\n  fn must be a fn of 4 args: a key, the reference, its old-state, its\n  new-state. Whenever the reference's state might have been changed,\n  any registered watches will have their functions called. The watch fn\n  will be called synchronously, on the agent's thread if an agent,\n  before any pending sends if agent or ref. Note that an atom's or\n  ref's state may have changed again prior to the fn call, so use\n  old/new-state rather than derefing the reference. Note also that watch\n  fns may be called from multiple threads simultaneously. Var watchers\n  are triggered only by root binding changes, not thread-local\n  set!s. Keys must be unique per reference, and can be used to remove\n  the watch with remove-watch, but are otherwise considered opaque by\n  the watch mechanism."}))
(when-let [v (resolve (quote clojure.core/agent))] (alter-meta! v fill {:arglists (quote ([state & options])), :doc "Creates and returns an agent with an initial value of state and\n  zero or more options (in any order):\n\n  :meta metadata-map\n\n  :validator validate-fn\n\n  :error-handler handler-fn\n\n  :error-mode mode-keyword\n\n  If metadata-map is supplied, it will become the metadata on the\n  agent. validate-fn must be nil or a side-effect-free fn of one\n  argument, which will be passed the intended new state on any state\n  change. If the new state is unacceptable, the validate-fn should\n  return false or throw an exception.  handler-fn is called if an\n  action throws an exception or if validate-fn rejects a new state --\n  see set-error-handler! for details.  The mode-keyword may be either\n  :continue (the default if an error-handler is given) or :fail (the\n  default if no error-handler is given) -- see set-error-mode! for\n  details."}))
(when-let [v (resolve (quote clojure.core/agent-error))] (alter-meta! v fill {:arglists (quote ([a])), :doc "Returns the exception thrown during an asynchronous action of the\n  agent if the agent is failed.  Returns nil if the agent is not\n  failed."}))
(when-let [v (resolve (quote clojure.core/agent-errors))] (alter-meta! v fill {:arglists (quote ([a])), :doc "DEPRECATED: Use 'agent-error' instead.\n  Returns a sequence of the exceptions thrown during asynchronous\n  actions of the agent."}))
(when-let [v (resolve (quote clojure.core/aget))] (alter-meta! v fill {:arglists (quote ([array idx] [array idx & idxs])), :doc "Returns the value at the index/indices. Works on Java arrays of all\n  types."}))
(when-let [v (resolve (quote clojure.core/alength))] (alter-meta! v fill {:arglists (quote ([array])), :doc "Returns the length of the Java array. Works on arrays of all\n  types."}))
(when-let [v (resolve (quote clojure.core/alias))] (alter-meta! v fill {:arglists (quote ([alias namespace-sym])), :doc "Add an alias in the current namespace to another\n  namespace. Arguments are two symbols: the alias to be used, and\n  the symbolic name of the target namespace. Use :as in the ns macro in preference\n  to calling this directly."}))
(when-let [v (resolve (quote clojure.core/all-ns))] (alter-meta! v fill {:arglists (quote ([])), :doc "Returns a sequence of all namespaces."}))
(when-let [v (resolve (quote clojure.core/alter))] (alter-meta! v fill {:arglists (quote ([ref fun & args])), :doc "Must be called in a transaction. Sets the in-transaction-value of\n  ref to:\n\n  (apply fun in-transaction-value-of-ref args)\n\n  and returns the in-transaction-value of ref."}))
(when-let [v (resolve (quote clojure.core/alter-meta!))] (alter-meta! v fill {:arglists (quote ([iref f & args])), :doc "Atomically sets the metadata for a namespace/var/ref/agent/atom to be:\n\n  (apply f its-current-meta args)\n\n  f must be free of side-effects"}))
(when-let [v (resolve (quote clojure.core/alter-var-root))] (alter-meta! v fill {:arglists (quote ([v f & args])), :doc "Atomically alters the root binding of var v by applying f to its\n  current value plus any args"}))
(when-let [v (resolve (quote clojure.core/amap))] (alter-meta! v fill {:arglists (quote ([a idx ret expr])), :doc "Maps an expression across an array a, using an index named idx, and\n  return value named ret, initialized to a clone of a, then setting \n  each element of ret to the evaluation of expr, returning the new \n  array ret."}))
(when-let [v (resolve (quote clojure.core/ancestors))] (alter-meta! v fill {:arglists (quote ([tag] [h tag])), :doc "Returns the immediate and indirect parents of tag, either via a Java type\n  inheritance relationship or a relationship established via derive. h\n  must be a hierarchy obtained from make-hierarchy, if not supplied\n  defaults to the global hierarchy"}))
(when-let [v (resolve (quote clojure.core/and))] (alter-meta! v fill {:arglists (quote ([] [x] [x & next])), :doc "Evaluates exprs one at a time, from left to right. If a form\n  returns logical false (nil or false), and returns that value and\n  doesn't evaluate any of the other expressions, otherwise it returns\n  the value of the last expr. (and) returns true."}))
(when-let [v (resolve (quote clojure.core/any?))] (alter-meta! v fill {:arglists (quote ([x])), :doc "Returns true given any argument."}))
(when-let [v (resolve (quote clojure.core/apply))] (alter-meta! v fill {:arglists (quote ([f args] [f x args] [f x y args] [f x y z args] [f a b c d & args])), :doc "Applies fn f to the argument list formed by prepending intervening arguments to args."}))
(when-let [v (resolve (quote clojure.core/areduce))] (alter-meta! v fill {:arglists (quote ([a idx ret init expr])), :doc "Reduces an expression across an array a, using an index named idx,\n  and return value named ret, initialized to init, setting ret to the \n  evaluation of expr at each step, returning ret."}))
(when-let [v (resolve (quote clojure.core/array-map))] (alter-meta! v fill {:arglists (quote ([] [& keyvals])), :doc "Constructs an array-map. If any keys are equal, they are handled as\n  if by repeated uses of assoc."}))
(when-let [v (resolve (quote clojure.core/as->))] (alter-meta! v fill {:arglists (quote ([expr name & forms])), :doc "Binds name to expr, evaluates the first form in the lexical context\n  of that binding, then binds name to that result, repeating for each\n  successive form, returning the result of the last form."}))
(when-let [v (resolve (quote clojure.core/aset))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on Java arrays of\n  reference types. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-boolean))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of boolean. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-byte))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of byte. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-char))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of char. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-double))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of double. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-float))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of float. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-int))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of int. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-long))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of long. Returns val."}))
(when-let [v (resolve (quote clojure.core/aset-short))] (alter-meta! v fill {:arglists (quote ([array idx val] [array idx idx2 & idxv])), :doc "Sets the value at the index/indices. Works on arrays of short. Returns val."}))
(when-let [v (resolve (quote clojure.core/assert))] (alter-meta! v fill {:arglists (quote ([x] [x message])), :doc "Evaluates expression x and throws an AssertionError with optional\n  message if x does not evaluate to logical true.\n\n  Assertion checks are omitted from compiled code if '*assert*' is\n  false."}))
(when-let [v (resolve (quote clojure.core/assoc))] (alter-meta! v fill {:arglists (quote ([map key val] [map key val & kvs])), :doc "assoc[iate]. When applied to a map, returns a new map of the\n    same (hashed/sorted) type, that contains the mapping of key(s) to\n    val(s). When applied to a vector, returns a new vector that\n    contains val at index. Note - index must be <= (count vector)."}))
(when-let [v (resolve (quote clojure.core/assoc!))] (alter-meta! v fill {:arglists (quote ([coll key val] [coll key val & kvs])), :doc "When applied to a transient map, adds mapping of key(s) to\n  val(s). When applied to a transient vector, sets the val at index.\n  Note - index must be <= (count vector). Returns coll."}))
(when-let [v (resolve (quote clojure.core/assoc-in))] (alter-meta! v fill {:arglists (quote ([m [k & ks] v])), :doc "Associates a value in a nested associative structure, where ks is a\n  sequence of keys and v is the new value and returns a new nested structure.\n  If any levels do not exist, hash-maps will be created."}))
(when-let [v (resolve (quote clojure.core/associative?))] (alter-meta! v fill {:arglists (quote ([coll])), :doc "Returns true if coll implements Associative"}))
(when-let [v (resolve (quote clojure.core/atom))] (alter-meta! v fill {:arglists (quote ([x] [x & options])), :doc "Creates and returns an Atom with an initial value of x and zero or\n  more options (in any order):\n\n  :meta metadata-map\n\n  :validator validate-fn\n\n  If metadata-map is supplied, it will become the metadata on the\n  atom. validate-fn must be nil or a side-effect-free fn of one\n  argument, which will be passed the intended new state on any state\n  change. If the new state is unacceptable, the validate-fn should\n  return false or throw an exception."}))
(when-let [v (resolve (quote clojure.core/await))] (alter-meta! v fill {:arglists (quote ([& agents])), :doc "Blocks the current thread (indefinitely!) until all actions\n  dispatched thus far, from this thread or agent, to the agent(s) have\n  occurred.  Will block on failed agents.  Will never return if\n  a failed agent is restarted with :clear-actions true or shutdown-agents was called."}))
(when-let [v (resolve (quote clojure.core/await-for))] (alter-meta! v fill {:arglists (quote ([timeout-ms & agents])), :doc "Blocks the current thread until all actions dispatched thus\n  far (from this thread or agent) to the agents have occurred, or the\n  timeout (in milliseconds) has elapsed. Returns logical false if\n  returning due to timeout, logical true otherwise."}))
(when-let [v (resolve (quote clojure.core/bigdec))] (alter-meta! v fill {:arglists (quote ([x])), :doc "Coerce to BigDecimal"}))
(when-let [v (resolve (quote clojure.core/bigint))] (alter-meta! v fill {:arglists (quote ([x])), :doc "Coerce to BigInt"}))
(when-let [v (resolve (quote clojure.core/biginteger))] (alter-meta! v fill {:arglists (quote ([x])), :doc "Coerce to BigInteger"}))
